-- Generated by node scripts/oss-draw-schema.mjs --write from server/schema/0001_current.sql.
-- Current draw storage excerpt; not a complete server database installation script.

CREATE FUNCTION public.lottery_proof_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.proof_plan IS NOT NULL AND NEW.proof_plan IS DISTINCT FROM OLD.proof_plan THEN
  RAISE EXCEPTION 'published lottery plan is immutable';
 END IF;
 IF OLD.status <> 'open' AND ROW(NEW.numbers,NEW.bonus,NEW.bonus_numbers,NEW.draw_proof) IS DISTINCT FROM ROW(OLD.numbers,OLD.bonus,OLD.bonus_numbers,OLD.draw_proof) THEN
  RAISE EXCEPTION 'completed lottery draw is immutable';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION public.lottery_ticket_plan_required() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected jsonb;
BEGIN
 IF NEW.game <> 'scratch' THEN
  SELECT proof_plan INTO expected FROM public.lottery_periods WHERE game=NEW.game AND period=NEW.period;
  IF expected IS NOT NULL AND NEW.proof_plan IS DISTINCT FROM expected THEN
   RAISE EXCEPTION 'ticket must bind the published lottery plan';
  END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE TABLE public.draw_commitments (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    game text NOT NULL,
    server_seed text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT draw_commitments_server_seed_check CHECK ((server_seed ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE public.lottery_day_user_stats (
    day date NOT NULL,
    game text NOT NULL,
    user_id uuid NOT NULL,
    tickets bigint DEFAULT 0 NOT NULL,
    stakes bigint DEFAULT 0 NOT NULL,
    sales bigint DEFAULT 0 NOT NULL,
    paid bigint DEFAULT 0 NOT NULL
);

CREATE TABLE public.lottery_periods (
    game text NOT NULL,
    period bigint NOT NULL,
    opens_at timestamp with time zone NOT NULL,
    draw_at timestamp with time zone NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    numbers smallint[],
    bonus smallint,
    bonus_numbers smallint[] DEFAULT '{}'::smallint[] NOT NULL,
    drawn_at timestamp with time zone,
    settled_at timestamp with time zone,
    tickets integer DEFAULT 0 NOT NULL,
    stakes integer DEFAULT 0 NOT NULL,
    players integer DEFAULT 0 NOT NULL,
    sales bigint DEFAULT 0 NOT NULL,
    paid bigint DEFAULT 0 NOT NULL,
    winners integer DEFAULT 0 NOT NULL,
    proof_plan jsonb,
    draw_proof jsonb,
    CONSTRAINT lottery_periods_proof_required CHECK (((proof_plan IS NULL) OR (status = 'open'::text) OR (draw_proof IS NOT NULL))),
    CONSTRAINT lottery_periods_status_check CHECK ((status = ANY (ARRAY['open'::text, 'drawn'::text, 'settled'::text])))
);

CREATE TABLE public.lottery_tickets (
    id uuid NOT NULL,
    purchase_id uuid NOT NULL,
    game text NOT NULL,
    period bigint NOT NULL,
    user_id uuid NOT NULL,
    bought_at timestamp with time zone DEFAULT now() NOT NULL,
    entry jsonb NOT NULL,
    stakes integer NOT NULL,
    multiplier smallint DEFAULT 1 NOT NULL,
    cost bigint NOT NULL,
    revealed boolean[],
    prize bigint,
    tier smallint,
    settled_at timestamp with time zone,
    proof_plan jsonb
);

CREATE TABLE public.lottery_winners (
    id uuid NOT NULL,
    game text NOT NULL,
    period bigint NOT NULL,
    user_id uuid,
    name text NOT NULL,
    tier smallint NOT NULL,
    prize bigint NOT NULL
);

ALTER TABLE ONLY public.draw_commitments
    ADD CONSTRAINT draw_commitments_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.draw_commitments
    ADD CONSTRAINT draw_commitments_user_id_game_key UNIQUE (user_id, game);

ALTER TABLE ONLY public.lottery_day_user_stats
    ADD CONSTRAINT lottery_day_user_stats_pkey PRIMARY KEY (day, game, user_id);

ALTER TABLE ONLY public.lottery_periods
    ADD CONSTRAINT lottery_periods_pkey PRIMARY KEY (game, period);

ALTER TABLE ONLY public.lottery_tickets
    ADD CONSTRAINT lottery_tickets_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.lottery_winners
    ADD CONSTRAINT lottery_winners_pkey PRIMARY KEY (game, period, id);

CREATE INDEX lottery_day_user_stats_user ON public.lottery_day_user_stats USING btree (user_id);

CREATE INDEX lottery_periods_drawn ON public.lottery_periods USING btree (game, drawn_at DESC) WHERE (status <> 'open'::text);

CREATE INDEX lottery_periods_retire ON public.lottery_periods USING btree (settled_at) WHERE (status = 'settled'::text);

CREATE INDEX lottery_periods_work ON public.lottery_periods USING btree (game, period) WHERE (status <> 'settled'::text);

CREATE INDEX lottery_tickets_feed ON public.lottery_tickets USING btree (game, bought_at DESC);

CREATE INDEX lottery_tickets_period_user ON public.lottery_tickets USING btree (game, period, user_id);

CREATE INDEX lottery_tickets_purchase ON public.lottery_tickets USING btree (purchase_id);

CREATE INDEX lottery_tickets_retire ON public.lottery_tickets USING btree (settled_at) WHERE (settled_at IS NOT NULL);

CREATE INDEX lottery_tickets_runtime_page ON public.lottery_tickets USING btree (game, period, id);

CREATE INDEX lottery_tickets_scratch_expiry ON public.lottery_tickets USING btree (bought_at, id) WHERE ((game = 'scratch'::text) AND (settled_at IS NULL));

CREATE INDEX lottery_tickets_unsettled ON public.lottery_tickets USING btree (game, period, user_id, id) WHERE (settled_at IS NULL);

CREATE INDEX lottery_tickets_user_recent ON public.lottery_tickets USING btree (user_id, game, bought_at DESC);

CREATE INDEX lottery_winners_board ON public.lottery_winners USING btree (game, period, prize DESC);

CREATE INDEX lottery_winners_user ON public.lottery_winners USING btree (user_id);

CREATE TRIGGER lottery_proof_immutable BEFORE UPDATE ON public.lottery_periods FOR EACH ROW EXECUTE FUNCTION public.lottery_proof_immutable();

CREATE TRIGGER lottery_ticket_plan_required BEFORE INSERT ON public.lottery_tickets FOR EACH ROW EXECUTE FUNCTION public.lottery_ticket_plan_required();
